def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if (0 <= yy < h and 0 <= xx < w and not seen[yy][xx]
                            and grid[yy][xx] == color):
                        seen[yy][xx] = True
                        q.append((yy, xx))
            rs = [y for y, x in cells]
            cs = [x for y, x in cells]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            comps.append((color, cells, r0, r1, c0, c1))

    markers = []
    for i, (color, cells, r0, r1, c0, c1) in enumerate(comps):
        mh, mw = r1 - r0 + 1, c1 - c0 + 1
        if mh < 3 or mw < 3 or len(cells) != mh + mw - 1:
            continue
        is_l = False
        for cr in (r0, r1):
            for cc in (c0, c1):
                expected = ({(cr, x) for x in range(c0, c1 + 1)} |
                            {(y, cc) for y in range(r0, r1 + 1)})
                if cells == expected:
                    is_l = True
                    break
            if is_l:
                break
        if is_l:
            markers.append((i, color, mh, mw))

    best = None
    for mi, marker_color, mh, mw in markers:
        want_h, want_w = (mh + 1) // 2, (mw + 1) // 2
        for j, (color, cells, r0, r1, c0, c1) in enumerate(comps):
            if j == mi or color == marker_color:
                continue
            oh, ow = r1 - r0 + 1, c1 - c0 + 1
            score = abs(oh - want_h) + abs(ow - want_w)
            candidate = (score, abs(oh * ow - want_h * want_w), mi, j)
            if best is None or candidate < best:
                best = candidate

    if best is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    marker_color = comps[best[2]][0]
    for r, c in comps[best[3]][1]:
        out[r][c] = marker_color
    return out
